select partsupp.ps_partkey, partsupp.ps_comment, partsupp.ps_availqty from partsupp join supplier on supplier.s_suppkey = partsupp.ps_suppkey where partsupp.ps_comment like '%unusual%' order by partsupp.ps_partkey;
select partsupp.ps_partkey, partsupp.ps_suppkey, partsupp.ps_availqty from partsupp join supplier on supplier.s_suppkey = partsupp.ps_suppkey where partsupp.ps_comment like '%special%' or partsupp.ps_availqty < 1000 order by partsupp.ps_suppkey;
select partsupp.ps_comment, count(*) as cnt from partsupp join supplier on supplier.s_suppkey = partsupp.ps_suppkey group by partsupp.ps_comment order by cnt desc;
select partsupp.ps_partkey, partsupp.ps_supplycost from partsupp join supplier on supplier.s_suppkey = partsupp.ps_suppkey where partsupp.ps_supplycost > 200 or partsupp.ps_availqty > 5000;
SELECT p.ps_partkey, p.ps_suppkey, p.ps_availqty, s.s_name FROM partsupp p JOIN supplier s ON s.s_suppkey = p.ps_suppkey WHERE p.ps_availqty > 1000 ORDER BY p.ps_partkey;
SELECT p.ps_partkey, p.ps_availqty FROM partsupp p JOIN supplier s ON s.s_suppkey = p.ps_suppkey WHERE s.s_suppkey IN (SELECT s_suppkey FROM supplier WHERE s_acctbal > 5000) AND p.ps_availqty > 1000;
SELECT partsupp.ps_partkey, partsupp.ps_availqty, partsupp.ps_supplycost, supplier.s_name FROM partsupp JOIN supplier ON supplier.s_suppkey = partsupp.ps_suppkey WHERE partsupp.ps_availqty > 1000 OR partsupp.ps_supplycost > 500 ORDER BY partsupp.ps_partkey;
select supplier.s_name, partsupp.ps_availqty, nation.n_name from partsupp join supplier on partsupp.ps_suppkey = supplier.s_suppkey join nation on supplier.s_nationkey = nation.n_nationkey where partsupp.ps_comment like '%special%' order by partsupp.ps_availqty desc;
select nation.n_name, supplier.s_suppkey, avg(partsupp.ps_supplycost) from nation join supplier on nation.n_nationkey = supplier.s_nationkey join partsupp on supplier.s_suppkey = partsupp.ps_suppkey group by nation.n_name, supplier.s_suppkey order by avg(partsupp.ps_supplycost) desc;
select nation.n_name, supplier.s_nationkey, partsupp.ps_partkey, sum(partsupp.ps_availqty) as total_qty from nation join supplier on nation.n_nationkey = supplier.s_nationkey join partsupp on supplier.s_suppkey = partsupp.ps_suppkey group by nation.n_name, supplier.s_nationkey, partsupp.ps_partkey order by total_qty desc;
select partsupp.ps_partkey, partsupp.ps_availqty, supplier.s_name from nation join supplier on nation.n_nationkey = supplier.s_nationkey join partsupp on supplier.s_suppkey = partsupp.ps_suppkey where partsupp.ps_comment like '%special%' order by partsupp.ps_availqty desc;
select supplier.s_suppkey, supplier.s_name, partsupp.ps_supplycost, partsupp.ps_availqty, nation.n_name from nation join supplier on nation.n_nationkey = supplier.s_nationkey join partsupp on supplier.s_suppkey = partsupp.ps_suppkey where partsupp.ps_comment like '%carefully%' order by partsupp.ps_supplycost desc, partsupp.ps_availqty desc;
select nation.n_name, supplier.s_suppkey, supplier.s_acctbal from nation join supplier on nation.n_nationkey = supplier.s_nationkey join partsupp on supplier.s_suppkey = partsupp.ps_suppkey where nation.n_comment like '%final%' or supplier.s_comment like '%final%';
select nation.n_name, supplier.s_suppkey from nation join supplier on nation.n_nationkey = supplier.s_nationkey join partsupp on supplier.s_suppkey = partsupp.ps_suppkey where nation.n_comment like '%blithely%' or supplier.s_comment like '%carefully%';
select o_orderkey, o_custkey, o_totalprice, o_orderdate from orders where o_comment like '%quickly%';
select o_orderkey, o_custkey from orders where o_orderstatus = 'O' and o_totalprice > (select avg(o_totalprice) from orders);
select o_orderkey, o_custkey, o_totalprice from orders o1 where o1.o_totalprice > (select avg(o2.o_totalprice) from orders o2 where o2.o_orderstatus = o1.o_orderstatus);
select o_orderkey, o_custkey from orders o where exists (select 1 from orders o2 where o2.o_custkey = o.o_custkey and o2.o_orderstatus = 'F');
select o_orderkey, o_custkey, o_totalprice, o_orderdate from orders where o_totalprice > 0 order by o_totalprice desc;
select o_orderkey, o_orderpriority, count(*) as cnt from orders group by o_orderkey, o_orderpriority order by cnt desc;
select customer.c_custkey, customer.c_name, orders.o_orderkey, orders.o_totalprice from customer join orders on customer.c_custkey = orders.o_custkey where customer.c_custkey in (select orders.o_custkey from orders where orders.o_totalprice > 200000) or upper(customer.c_name) like '%CUSTOMER#%';
select customer.c_name, count(orders.o_orderkey) as order_cnt from customer join orders on customer.c_custkey = orders.o_custkey group by customer.c_name order by order_cnt desc;
select customer.c_custkey, customer.c_name, orders.o_orderkey from customer join orders on customer.c_custkey = orders.o_custkey where customer.c_name like '%test%' or customer.c_custkey in (select orders.o_custkey from orders where orders.o_totalprice > 100000);
select customer.c_phone, customer.c_acctbal, orders.o_orderkey from customer join orders on customer.c_custkey = orders.o_custkey where exists (select 1 from orders o2 where o2.o_custkey = customer.c_custkey and o2.o_totalprice > 100000) or customer.c_nationkey between 1 and 10;
select customer.c_mktsegment, sum(orders.o_totalprice) as total_spent, count(*) as order_count from customer join orders on customer.c_custkey = orders.o_custkey group by customer.c_mktsegment order by total_spent desc;
SELECT customer.*, orders.* FROM customer JOIN orders ON customer.c_custkey = orders.o_custkey WHERE customer.c_comment LIKE '%unusual%' ORDER BY customer.c_name;
SELECT customer.c_mktsegment, COUNT(DISTINCT orders.o_orderkey) AS order_count, SUM(orders.o_totalprice) AS total_revenue FROM customer JOIN orders ON customer.c_custkey = orders.o_custkey GROUP BY customer.c_mktsegment ORDER BY order_count DESC;
SELECT part.p_partkey, partsupp.ps_availqty FROM part JOIN partsupp ON part.p_partkey = partsupp.ps_partkey WHERE part.p_partkey IN (SELECT ps_partkey FROM partsupp WHERE ps_supplycost > 800 GROUP BY ps_partkey HAVING COUNT(*) > 1);
SELECT part.p_partkey, partsupp.ps_supplycost FROM part JOIN partsupp ON part.p_partkey = partsupp.ps_partkey WHERE part.p_name ~ '^Manufacturer' OR part.p_brand LIKE '%Brand%' ORDER BY partsupp.ps_supplycost;
SELECT part.p_mfgr, part.p_name, SUM(partsupp.ps_supplycost) AS total_cost, COUNT(*) AS cnt FROM part JOIN partsupp ON part.p_partkey = partsupp.ps_partkey GROUP BY part.p_mfgr, part.p_name HAVING SUM(partsupp.ps_supplycost) > 1000 ORDER BY total_cost DESC;
SELECT p.p_partkey, p.p_name, ps.ps_supplycost FROM part p JOIN partsupp ps ON p.p_partkey = ps.ps_partkey WHERE ps.ps_comment LIKE '%careful%' ORDER BY p.p_name;
SELECT p.p_partkey, ps.ps_availqty FROM part p JOIN partsupp ps ON p.p_partkey = ps.ps_partkey WHERE ps.ps_comment LIKE '%special%';
SELECT p.p_partkey, p.p_name, ps.ps_availqty FROM part p JOIN partsupp ps ON p.p_partkey = ps.ps_partkey WHERE ps.ps_comment LIKE '%careful%' ORDER BY ps.ps_supplycost;
SELECT p.p_partkey, p.p_name FROM part p JOIN partsupp ps ON p.p_partkey = ps.ps_partkey WHERE p.p_partkey NOT IN (SELECT ps_partkey FROM partsupp WHERE ps_availqty < 100);
SELECT part.p_partkey, part.p_name, supplier.s_comment FROM part JOIN partsupp ON part.p_partkey = partsupp.ps_partkey JOIN supplier ON partsupp.ps_suppkey = supplier.s_suppkey WHERE partsupp.ps_supplycost > (SELECT AVG(ps_supplycost) FROM partsupp) OR part.p_mfgr LIKE '%Manufacturer%';
SELECT part.p_brand, COUNT(*) AS cnt, AVG(partsupp.ps_supplycost) AS avg_cost FROM part JOIN partsupp ON part.p_partkey = partsupp.ps_partkey JOIN supplier ON partsupp.ps_suppkey = supplier.s_suppkey GROUP BY part.p_brand HAVING COUNT(*) > 100 ORDER BY cnt DESC;
select part.p_name, supplier.s_name, partsupp.ps_comment from part join partsupp on part.p_partkey = partsupp.ps_partkey join supplier on partsupp.ps_suppkey = supplier.s_suppkey where partsupp.ps_availqty > 500;
select part.p_mfgr, sum(partsupp.ps_supplycost) as total_cost, count(*) as cnt from part join partsupp on part.p_partkey = partsupp.ps_partkey join supplier on partsupp.ps_suppkey = supplier.s_suppkey group by part.p_mfgr order by total_cost desc;
select part.p_partkey, supplier.s_comment from part join partsupp on part.p_partkey = partsupp.ps_partkey join supplier on partsupp.ps_suppkey = supplier.s_suppkey where exists (select 1 from partsupp as ps2 where ps2.ps_partkey = part.p_partkey and ps2.ps_availqty > 5000 and ps2.ps_comment like '%special%');
SELECT part.*, partsupp.*, supplier.* FROM part JOIN partsupp ON part.p_partkey = partsupp.ps_partkey JOIN supplier ON partsupp.ps_suppkey = supplier.s_suppkey WHERE part.p_type LIKE '%STEEL%';
SELECT part.p_mfgr, supplier.s_name, partsupp.ps_availqty FROM part JOIN partsupp ON part.p_partkey = partsupp.ps_partkey JOIN supplier ON partsupp.ps_suppkey = supplier.s_suppkey WHERE part.p_partkey IN (SELECT p_partkey FROM part WHERE p_brand = 'Brand#41');
select ps_partkey, ps_suppkey from partsupp where ps_comment like '%quickly%';
select ps_partkey, ps_availqty from partsupp where ps_supplycost > (select avg(ps_supplycost) from partsupp) and ps_comment like '%ironic%';
select ps_comment, count(*) from partsupp group by ps_comment having count(*) > 1 order by count(*) desc;
SELECT ps_partkey, ps_suppkey, ps_availqty FROM partsupp WHERE ps_supplycost > 500.0 ORDER BY ps_availqty DESC;
SELECT ps_partkey, ps_suppkey, ps_availqty FROM partsupp WHERE ps_supplycost > (SELECT AVG(ps_supplycost) FROM partsupp) AND (ps_comment LIKE '%carefully%' OR ps_comment LIKE '%quickly%');
select ps_partkey, ps_suppkey from partsupp p1 where exists (select 1 from partsupp p2 where p2.ps_partkey = p1.ps_partkey and p2.ps_supplycost > p1.ps_supplycost * 1.1);
SELECT ps_partkey, ps_suppkey, ps_availqty FROM partsupp WHERE ps_comment LIKE '%special%' ORDER BY ps_availqty DESC;
select customer.c_mktsegment, nation.n_name, count(distinct customer.c_custkey) as cust_cnt from customer join nation on customer.c_nationkey = nation.n_nationkey join supplier on nation.n_nationkey = supplier.s_nationkey where customer.c_comment like '%regular%' group by customer.c_mktsegment, nation.n_name order by cust_cnt desc;
select customer.c_mktsegment, nation.n_regionkey, sum(customer.c_acctbal) as total_bal, avg(supplier.s_acctbal) as avg_supp_bal from customer join nation on customer.c_nationkey = nation.n_nationkey join supplier on nation.n_nationkey = supplier.s_nationkey group by customer.c_mktsegment, nation.n_regionkey order by total_bal desc, avg_supp_bal asc;
select customer.c_name, nation.n_name, supplier.s_name from customer join nation on customer.c_nationkey = nation.n_nationkey join supplier on nation.n_nationkey = supplier.s_nationkey where customer.c_address like '%abc%';
select customer.c_name, nation.n_name, supplier.s_acctbal from customer join nation on customer.c_nationkey = nation.n_nationkey join supplier on nation.n_nationkey = supplier.s_nationkey where customer.c_custkey in (select s_suppkey from supplier where s_acctbal > 9000);
select customer.c_mktsegment, nation.n_regionkey, sum(supplier.s_acctbal) as total_supp_bal from customer join nation on customer.c_nationkey = nation.n_nationkey join supplier on nation.n_nationkey = supplier.s_nationkey group by customer.c_mktsegment, nation.n_regionkey order by total_supp_bal desc;
SELECT customer.c_name, nation.n_name, supplier.s_name FROM customer JOIN nation ON customer.c_nationkey = nation.n_nationkey JOIN supplier ON nation.n_nationkey = supplier.s_nationkey WHERE customer.c_comment LIKE '%carefully%';
SELECT customer.c_phone, nation.n_name, supplier.s_acctbal FROM customer JOIN nation ON customer.c_nationkey = nation.n_nationkey JOIN supplier ON nation.n_nationkey = supplier.s_nationkey WHERE UPPER(customer.c_name) LIKE '%CUSTOMER%' ORDER BY customer.c_phone;
SELECT orders.o_orderdate, lineitem.l_quantity, partsupp.ps_supplycost FROM orders JOIN lineitem ON orders.o_orderkey = lineitem.l_orderkey JOIN partsupp ON lineitem.l_partkey = partsupp.ps_partkey AND lineitem.l_suppkey = partsupp.ps_suppkey WHERE partsupp.ps_comment LIKE '%express%';
SELECT orders.o_orderstatus, COUNT(*) AS cnt, SUM(lineitem.l_extendedprice) AS total_price FROM orders JOIN lineitem ON orders.o_orderkey = lineitem.l_orderkey JOIN partsupp ON lineitem.l_partkey = partsupp.ps_partkey AND lineitem.l_suppkey = partsupp.ps_suppkey GROUP BY orders.o_orderstatus ORDER BY total_price DESC;
SELECT orders.o_orderdate, AVG(lineitem.l_quantity) AS avg_qty FROM orders JOIN lineitem ON orders.o_orderkey = lineitem.l_orderkey JOIN partsupp ON lineitem.l_partkey = partsupp.ps_partkey AND lineitem.l_suppkey = partsupp.ps_suppkey GROUP BY orders.o_orderdate ORDER BY avg_qty DESC;
SELECT orders.o_orderpriority, SUM(lineitem.l_quantity) AS total_qty FROM orders JOIN lineitem ON orders.o_orderkey = lineitem.l_orderkey JOIN partsupp ON lineitem.l_partkey = partsupp.ps_partkey AND lineitem.l_suppkey = partsupp.ps_suppkey GROUP BY orders.o_orderpriority ORDER BY total_qty DESC;
select lineitem.l_returnflag, lineitem.l_linestatus, count(*) as cnt, sum(lineitem.l_quantity) as total_qty from lineitem join partsupp on lineitem.l_partkey = partsupp.ps_partkey and lineitem.l_suppkey = partsupp.ps_suppkey join supplier on partsupp.ps_suppkey = supplier.s_suppkey group by lineitem.l_returnflag, lineitem.l_linestatus having count(*) > 1000 order by cnt desc;
select partsupp.ps_suppkey, count(*) as cnt from lineitem join partsupp on lineitem.l_partkey = partsupp.ps_partkey and lineitem.l_suppkey = partsupp.ps_suppkey group by partsupp.ps_suppkey order by cnt desc;
select supplier.s_nationkey, count(*) as cnt from lineitem join partsupp on lineitem.l_partkey = partsupp.ps_partkey and lineitem.l_suppkey = partsupp.ps_suppkey join supplier on partsupp.ps_suppkey = supplier.s_suppkey group by supplier.s_nationkey order by cnt desc;
select l.l_returnflag, l.l_linestatus, sum(l.l_quantity) as total_qty from lineitem l join partsupp ps on l.l_partkey = ps.ps_partkey and l.l_suppkey = ps.ps_suppkey group by l.l_returnflag, l.l_linestatus order by l.l_returnflag, l.l_linestatus;
select p.p_brand, p.p_type, sum(ps.ps_availqty) as total_avail, avg(l.l_quantity) as avg_qty from lineitem l join partsupp ps on l.l_partkey = ps.ps_partkey and l.l_suppkey = ps.ps_suppkey join part p on ps.ps_partkey = p.p_partkey group by p.p_brand, p.p_type order by total_avail desc;
select l.l_shipmode, sum(l.l_quantity) as total_qty, avg(l.l_extendedprice) as avg_price from lineitem l join partsupp ps on l.l_partkey = ps.ps_partkey and l.l_suppkey = ps.ps_suppkey group by l.l_shipmode order by total_qty desc;
SELECT o_orderkey, o_orderdate FROM orders WHERE o_comment LIKE '%express%';
select c_custkey, c_phone, n_name from customer join nation on c_nationkey = n_nationkey where c_custkey not in (select c_custkey from customer where c_comment like '%x%');
select lineitem.l_orderkey, lineitem.l_partkey, lineitem.l_linenumber from lineitem join partsupp on lineitem.l_suppkey = partsupp.ps_suppkey where partsupp.ps_comment like '%cajole%';
select part.p_brand, sum(lineitem.l_extendedprice) as total_revenue from lineitem join partsupp on lineitem.l_partkey = partsupp.ps_partkey and lineitem.l_suppkey = partsupp.ps_suppkey join part on partsupp.ps_partkey = part.p_partkey where part.p_size > 15 group by part.p_brand having sum(lineitem.l_extendedprice) > 10000 order by total_revenue desc;
select lineitem.l_orderkey, lineitem.l_shipdate, partsupp.ps_supplycost from lineitem join partsupp on lineitem.l_suppkey = partsupp.ps_suppkey join part on partsupp.ps_partkey = part.p_partkey where part.p_comment like '%carefully%' order by lineitem.l_shipdate;
select lineitem.l_orderkey, lineitem.l_partkey, lineitem.l_linenumber from lineitem join partsupp on lineitem.l_suppkey = partsupp.ps_suppkey where exists (select 1 from part where part.p_partkey = partsupp.ps_partkey and part.p_retailprice > 1000 and part.p_comment not like '%special%') order by lineitem.l_orderkey;
select customer.c_custkey, customer.c_acctbal from customer join nation on customer.c_nationkey = nation.n_nationkey where exists (select 1 from customer c2 where c2.c_nationkey = customer.c_nationkey and c2.c_custkey > 800000) order by customer.c_acctbal desc;
SELECT customer.c_comment, COUNT(*) AS cnt FROM customer JOIN nation ON customer.c_nationkey = nation.n_nationkey GROUP BY customer.c_comment ORDER BY cnt DESC;
SELECT customer.c_mktsegment, customer.c_phone, AVG(customer.c_acctbal) AS avg_bal FROM customer JOIN nation ON customer.c_nationkey = nation.n_nationkey GROUP BY customer.c_mktsegment, customer.c_phone HAVING AVG(customer.c_acctbal) > 5000 ORDER BY avg_bal DESC;
SELECT customer.c_name, customer.c_address, nation.n_name, SUM(customer.c_acctbal) AS total_acctbal FROM customer JOIN nation ON customer.c_nationkey = nation.n_nationkey GROUP BY customer.c_name, customer.c_address, nation.n_name ORDER BY total_acctbal DESC;
SELECT customer.c_custkey, customer.c_name, customer.c_address, nation.n_name, COUNT(customer.c_phone) AS phone_count FROM customer JOIN nation ON customer.c_nationkey = nation.n_nationkey GROUP BY customer.c_custkey, customer.c_name, customer.c_address, nation.n_name ORDER BY phone_count DESC;
select partsupp.ps_suppkey, supplier.s_phone from partsupp join supplier on supplier.s_suppkey = partsupp.ps_suppkey where partsupp.ps_supplycost > (select avg(ps_supplycost) from partsupp);
select partsupp.ps_suppkey, avg(partsupp.ps_supplycost) as avg_cost, sum(partsupp.ps_availqty) as total_qty from partsupp join supplier on supplier.s_suppkey = partsupp.ps_suppkey group by partsupp.ps_suppkey order by total_qty desc;
select partsupp.ps_suppkey, supplier.s_name from partsupp join supplier on supplier.s_suppkey = partsupp.ps_suppkey where partsupp.ps_supplycost > 500.00 order by partsupp.ps_suppkey desc;
select partsupp.ps_partkey, supplier.s_name from partsupp join supplier on supplier.s_suppkey = partsupp.ps_suppkey where exists (select 1 from partsupp ps2 where ps2.ps_suppkey = partsupp.ps_suppkey and ps2.ps_availqty > 5000);
select supplier.s_name, partsupp.ps_availqty from nation join supplier on nation.n_nationkey = supplier.s_nationkey join partsupp on supplier.s_suppkey = partsupp.ps_suppkey where exists (select 1 from nation n2 where n2.n_regionkey = nation.n_regionkey and n2.n_nationkey < 10) and partsupp.ps_supplycost > 100;
SELECT partsupp.ps_partkey, partsupp.ps_availqty FROM nation JOIN supplier ON nation.n_nationkey = supplier.s_nationkey JOIN partsupp ON supplier.s_suppkey = partsupp.ps_suppkey WHERE partsupp.ps_comment LIKE '%special%';
select nation.n_name, supplier.s_name, partsupp.ps_partkey, partsupp.ps_supplycost, partsupp.ps_availqty from nation join supplier on nation.n_nationkey = supplier.s_nationkey join partsupp on supplier.s_suppkey = partsupp.ps_suppkey where partsupp.ps_comment like '%iron%';
select supplier.s_name, partsupp.ps_partkey, partsupp.ps_supplycost from nation join supplier on nation.n_nationkey = supplier.s_nationkey join partsupp on supplier.s_suppkey = partsupp.ps_suppkey where upper(nation.n_name) like 'ROM%' or partsupp.ps_comment like '%carefully%';
select o_orderkey, o_orderdate, o_totalprice from orders where o_totalprice > 100000;
select o_orderkey, o_orderpriority from orders where o_comment like '%unusual%' or o_comment like '%quick%';
select o_orderkey, o_orderdate from orders where o_orderkey in (select o_orderkey from orders where o_totalprice > 50000);
select o_orderkey, o_totalprice from orders where o_comment like '%express%';
SELECT customer.c_custkey, customer.c_mktsegment, orders.o_orderpriority, COUNT(*) AS cnt FROM customer JOIN orders ON customer.c_custkey = orders.o_custkey WHERE orders.o_comment LIKE '%carefully%' OR customer.c_name LIKE '%Customer#%' GROUP BY customer.c_custkey, customer.c_mktsegment, orders.o_orderpriority ORDER BY customer.c_custkey;
SELECT customer.c_mktsegment, orders.o_orderstatus, AVG(orders.o_totalprice) AS avg_price, COUNT(*) AS order_count FROM customer JOIN orders ON customer.c_custkey = orders.o_custkey GROUP BY customer.c_mktsegment, orders.o_orderstatus ORDER BY order_count DESC, avg_price DESC;
SELECT customer.c_custkey, customer.c_name, orders.o_orderkey, orders.o_totalprice FROM customer JOIN orders ON customer.c_custkey = orders.o_custkey WHERE customer.c_custkey IN (SELECT o_custkey FROM orders WHERE o_totalprice > 100000) ORDER BY customer.c_custkey;
SELECT customer.c_nationkey, MIN(orders.o_orderdate) AS first_order_date, MAX(orders.o_orderdate) AS last_order_date, COUNT(*) AS order_count FROM customer JOIN orders ON customer.c_custkey = orders.o_custkey GROUP BY customer.c_nationkey ORDER BY order_count DESC;
SELECT customer.c_custkey, customer.c_mktsegment FROM customer JOIN orders ON customer.c_custkey = orders.o_custkey WHERE NOT EXISTS (SELECT 1 FROM orders o2 WHERE o2.o_custkey = customer.c_custkey AND o2.o_orderstatus = 'F') ORDER BY customer.c_custkey;
SELECT customer.c_custkey, customer.c_name, orders.o_orderkey, orders.o_orderdate FROM customer JOIN orders ON customer.c_custkey = orders.o_custkey WHERE customer.c_name LIKE '%Customer%';
SELECT customer.c_name, customer.c_address, count(orders.o_orderkey) AS order_count FROM customer JOIN orders ON customer.c_custkey = orders.o_custkey GROUP BY customer.c_name, customer.c_address HAVING count(orders.o_orderkey) > 10 ORDER BY order_count DESC;
SELECT customer.c_custkey, customer.c_name, customer.c_comment, orders.o_orderkey FROM customer JOIN orders ON customer.c_custkey = orders.o_custkey WHERE customer.c_comment LIKE '%pinto%';
select customer.c_custkey, region.r_name, count(*) as cnt from customer join nation on customer.c_nationkey=nation.n_nationkey join region on nation.n_regionkey=region.r_regionkey where customer.c_comment like '%special%' or nation.n_name in (select n_name from nation where n_regionkey in (select r_regionkey from region where r_name like '%A%')) group by customer.c_custkey, region.r_name order by cnt desc;
SELECT part.p_mfgr, partsupp.ps_supplycost FROM part JOIN partsupp ON partsupp.ps_partkey = part.p_partkey WHERE part.p_type LIKE '%COPPER' OR part.p_brand = 'Brand#41';
SELECT part.p_partkey, part.p_name, partsupp.ps_supplycost FROM part JOIN partsupp ON partsupp.ps_partkey = part.p_partkey WHERE part.p_retailprice > 1000;
SELECT part.p_brand, partsupp.ps_comment FROM part JOIN partsupp ON partsupp.ps_partkey = part.p_partkey WHERE partsupp.ps_comment LIKE '%special%' OR part.p_type = 'ECONOMY PLATED COPPER';
